import os
from uuid import UUID
from typing import Optional

from fastapi import Request
from starlette.exceptions import HTTPException

from service54.actions import EntityActionMixin
from service54.auth_perms.fast_api.exceptions import Forbidden
from service54.actions.backup_sync import run_backup
from service54.core.exceptions import EntityNotFound

from service54.auth_perms.fast_api.utils import get_current_actor

# Simple in-memory storage for backup results
# In production, consider using Redis or a database for persistence
_backup_storage: dict[str, dict] = {}


class EntityBackupMixin(EntityActionMixin):
    def __init__(self, data, request) -> None:
        self.request = request
        self.affix_uuid = None
        self.perm_uuid = None
        self.actor = get_current_actor(request=request)

        self.backup_uuid: str = data.get("backup_uuid")
        self.backup_info = None
        self._load_backup()

        if not self.check_exist():
            raise EntityNotFound(message="There is no entity with such uuid")

        if not self.check_perm("read"):
            raise Forbidden

    def _load_backup(self):
        if self.backup_uuid not in _backup_storage:
            raise EntityNotFound(message="Entity backup not found or expired.")

        self._backup_info = _backup_storage[self.backup_uuid]
        self.entity_uuid = UUID(self._backup_info.get("entity_uuid"))
        self.partition = self._backup_info.get("partition")
        self.backup_path = self._backup_info.get("backup_path")
        self.status = self._backup_info.get("status", "UNKNOWN")


class EntityBackupCreateAction(EntityActionMixin):

    def __init__(self, data, request: Request):
        super().__init__(request)
        self.entity_uuid = data.get("entity_uuid")

        if not self.check_exist():
            raise EntityNotFound(message="There is no entity with such uuid")

        if not self.check_perm("read"):
            raise Forbidden

    def execute(self):
        try:
            result = run_backup(self.entity_uuid, self.partition)
            backup_uuid = result["backup_uuid"]
            _backup_storage[backup_uuid] = result
            return {"backup_uuid": backup_uuid}
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"Backup failed: {str(e)}")


class EntityBackupStatusAction(EntityBackupMixin):

    def execute(self):
        result = {
            "backup_uuid": self.backup_uuid,
            "entity_uuid": str(self.entity_uuid),
            "partition": self.partition,
            "status": self.status
        }
        return result


class EntityBackupReadAction(EntityBackupMixin):

    def execute(self):
        if self.status != "SUCCESS":
            raise HTTPException(
                status_code=400, detail=f"Task not finished yet (status: {self.status})"
            )

        if not self.backup_path or not os.path.exists(self.backup_path):
            raise EntityNotFound(message="Backup file not found")

        return self.backup_path
